import{_ as t,o as i,c as a,ah as r}from"./chunks/framework.Bja9t6Wf.js";const u=JSON.parse('{"title":"Research: The Christian Pilnacek Case","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/der-fall-pilnacek.md","filePath":"en/recherche/der-fall-pilnacek.md"}'),n={name:"en/recherche/der-fall-pilnacek.md"};function o(s,e,c,l,h,m){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="research-the-christian-pilnacek-case" tabindex="-1">Research: The Christian Pilnacek Case <a class="header-anchor" href="#research-the-christian-pilnacek-case" aria-label="Permalink to &quot;Research: The Christian Pilnacek Case&quot;">​</a></h1><p><strong>The secret recordings and the &quot;shutting down&quot; of investigations.</strong></p><p>Christian Pilnacek was the most powerful official in the Austrian Ministry of Justice for over a decade. His case and the associated parliamentary committee of inquiry (2025–2026) form the dark interface between politics and justice in our mockumentary.</p><hr><h2 id="key-elements" tabindex="-1">Key Elements <a class="header-anchor" href="#key-elements" aria-label="Permalink to &quot;Key Elements&quot;">​</a></h2><h3 id="_1-the-secret-recordings-november-2023" tabindex="-1">1. The Secret Recordings (November 2023) <a class="header-anchor" href="#_1-the-secret-recordings-november-2023" aria-label="Permalink to &quot;1. The Secret Recordings (November 2023)&quot;">​</a></h3><p>Shortly after his death in October 2023, audio recordings made secretly during a meeting in a Vienna restaurant became public. In them, Pilnacek makes serious allegations against the ÖVP:</p><ul><li><strong>The Sobotka Intervention:</strong> Pilnacek claims that Wolfgang Sobotka asked him why he didn&#39;t &quot;shut down&quot; investigations.</li><li><strong>Political Pressure:</strong> He describes how the People&#39;s Party attempted for years to influence proceedings against its prominent members.</li></ul><h3 id="_2-the-committee-of-inquiry-2025–2026" tabindex="-1">2. The Committee of Inquiry (2025–2026) <a class="header-anchor" href="#_2-the-committee-of-inquiry-2025–2026" aria-label="Permalink to &quot;2. The Committee of Inquiry (2025–2026)&quot;">​</a></h3><p>Since November 2025, a dedicated committee has been investigating allegations of abuse of power.</p><ul><li><strong>Findings of the Kreutner Commission:</strong> A 2024 commission under Martin Kreutner established a &quot;highly problematic two-tier justice system&quot; in Austria.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>The Pilnacek case is the modern equivalent of the &quot;Archive of Silence&quot; for our project.</p><ul><li><strong>Judicial Pointillism:</strong> A system in which not one large law is broken, but many small interventions, phone calls, and informal meetings (as in the recording) distort the overall picture of the rule of law.</li></ul><hr><p><em>Sources: Protocols of the Pilnacek Inquiry Committee (2026), report of the Kreutner Commission (2024), reporting by Standard, ORF, and Profil.</em></p>',17)])])}const f=t(n,[["render",o]]);export{u as __pageData,f as default};
